  const inv2 = createIssuedInvoice('C-001', '2026-10-02');
  const result = vatSummary([inv1, inv2]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  // C-001 is gold tier with 5% discount applied to each invoice
  // Each: 996 * 95% = 946.2 → 946, total base = 1892
  assert.equal(result[0].base, 1892);
});

test('vatSummary: handles line discounts', () => {
  const created = createInvoice({
    customerId: 'C-002', // standard tier, no auto discount
    issueDate: '2026-10-01',
    lines: [
      { sku: 'PHOTO-LIC', qty: 1, discountPercent: 10 }, // 996 * 90% base
    ],
  });
  const invoice = issueInvoice(created.value, []).value;
  const result = vatSummary([invoice]);
  assert.equal(result[0].rate, 21);
  // discount = roundCents(996 * 10 / 100) = roundCents(99.6) = 100
  // base = 996 - 100 = 896
  assert.equal(result[0].base, 896);
});

test('vatSummary: handles tier discounts', () => {
  // C-001 is gold tier with 5% discount
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'PHOTO-LIC', qty: 1 }, // No explicit discount, gets 5% tier discount
    ],
  });
  const invoice = issueInvoice(created.value, []).value;
  const result = vatSummary([invoice]);
  // base = 996 * 95% = 946.2 → 946
  assert.equal(result[0].base, 946);
  // VAT = 946 * 21 / 100 = 198.66 → 199
  assert.equal(result[0].vat, 199);
});

test('vatSummary: multiple lines with same VAT rate', () => {
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'PHOTO-LIC', qty: 2 },
      { sku: 'FONT-LIC', qty: 1 },
    ],
  });
  const invoice = issueInvoice(created.value, []).value;
  const result = vatSummary([invoice]);
  // PHOTO-LIC: 996 * 2 = 1992 with 5% discount (C-001 gold)
  // Discount = roundCents(1992 * 5 / 100) = roundCents(99.6) = 100
  // Base = 1992 - 100 = 1892
  // FONT-LIC: 1010 * 1 = 1010 with 5% discount
  // Discount = roundCents(1010 * 5 / 100) = roundCents(50.5) = 50 (banker's rounding)
  // Base = 1010 - 50 = 960
  // Total base at 21%: 1892 + 960 = 2852
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 2852);
});

